293	static long sys_openat(int dirfd, const char* path, int flags, int mode)
294	{
295	  const int nflags = linux_to_newlib_open_flags(flags);
296	  /* AT_FDCWD is openat's "resolve like open() would" case (POSIX): route
297	   * it through VH_SYS_OPEN, which threads mode correctly. VH_SYS_OPENAT's
298	   * host handler drops the mode argument entirely (its own arity -- see
299	   * andes_ae350.c case 20), so a real dirfd-relative O_CREAT open (not
300	   * exercised by any current fixture) is the one documented gap left by
301	   * this relay, same "loud, low-severity, documented" tier as U2's
302	   * staging-dir leak. */
303	  if (dirfd == AT_FDCWD)
304	    return htif_call_str(VH_SYS_OPEN, path, (uint64_t) nflags, (uint64_t) mode);
305	  if (htif_win_store_str(0, path) == (size_t) -1) return -EINVAL;
306	  return htif_syscall(VH_SYS_OPENAT, (uint64_t) dirfd, WIN_DATA_VA,
307	                      (uint64_t) nflags, 0);
308	}
