327	/* fstatat honors dirfd and AT_SYMLINK_NOFOLLOW natively on the host side
328	 * (its own fstatat() call), so both forward as-is -- no AT_FDCWD special
329	 * case needed here (unlike openat, this host handler already threads
330	 * every argument fstatat's real ABI has). This is also where glibc's
331	 * stat()/lstat() land: riscv64 has no bare stat/lstat syscalls. */
332	static long sys_fstatat(int dirfd, const char* path, struct vlinux_stat* buf,
333	                        int flags)
334	{
335	  size_t stoff = htif_win_store_str(0, path);
336	  /* stoff+24: room for host_stat_mode_size's aligned scratch block right
337	   * after the path string, same bound vplat's own _fstatat/_stat apply. */
338	  if (stoff == (size_t) -1 || stoff + 24 > WIN_DATA_SIZE) return -EINVAL;
339	  long r = htif_syscall(VH_SYS_FSTATAT, (uint64_t) dirfd, WIN_DATA_VA,
340	                        WIN_DATA_VA + stoff, (uint64_t) flags);
341	  if (r == 0) {
342	    unsigned int mode; unsigned long size;
343	    host_stat_mode_size(stoff, &mode, &size);
344	    fill_stat_from_host(buf, mode, size);
345	  }
346	  return r;
347	}
